   199    objidx_t pop_pack ()
   200    {
   201      object_t *obj = current;
   202      if (unlikely (!obj)) return 0;
   203      current = current->next;
   204      obj->tail = head;
   205      obj->next = nullptr;
   206      unsigned len = obj->tail - obj->head;
   207      head = obj->head; /* Rewind head. */
