   429                       + (this->end  - this->tail);
   430      char *p = (char *) malloc (len);
   431      if (p)
   432      {
   433        memcpy (p, this->start, this->head - this->start);
   434        memcpy (p + (this->head - this->start), this->tail, this->end - this->tail);
   435      }
   436      else
   437        return hb_bytes_t ();
   438      return hb_bytes_t (p, len);
